package com.italiano2774.nativeapp;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class EmergencyRepository{
 private static EmergencyRepository instance;private final List<EmergencyCategory> categories=new ArrayList<>();
 private EmergencyRepository(Context c){try(BufferedReader br=new BufferedReader(new InputStreamReader(c.getAssets().open("emergency_phrases.json"),StandardCharsets.UTF_8))){StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);JSONArray arr=new JSONArray(sb.toString());for(int i=0;i<arr.length();i++){JSONObject o=arr.getJSONObject(i);EmergencyCategory ec=new EmergencyCategory();ec.id=o.optString("id");ec.category=o.optString("category");JSONArray ps=o.optJSONArray("phrases");if(ps!=null)for(int j=0;j<ps.length();j++){JSONObject x=ps.getJSONObject(j);EmergencyPhrase p=new EmergencyPhrase();p.it=x.optString("it");p.zh=x.optString("zh");p.category=ec.category;ec.phrases.add(p);}categories.add(ec);}}catch(Exception e){throw new RuntimeException("Failed to load emergency_phrases.json",e);}}
 public static synchronized EmergencyRepository get(Context c){if(instance==null)instance=new EmergencyRepository(c.getApplicationContext());return instance;}public List<EmergencyCategory> categories(){return categories;}public List<EmergencyPhrase> all(){List<EmergencyPhrase> out=new ArrayList<>();for(EmergencyCategory c:categories)out.addAll(c.phrases);return out;}public EmergencyCategory byName(String name){for(EmergencyCategory c:categories)if(c.category.equals(name))return c;return null;}
}
